}

/****************************************************************************
 * Name: up_putc
 *
 * Description:
 *   Provide priority, low-level access to support OS debug writes.
 *
 * Input Parameters:
 *   ch            - Character to be output to the console.
 *
 * Returned Value:
 *   On success, the character is echoed back to the caller. A negated
 *   errno value is returned on any failure.
 *
 ****************************************************************************/

void up_putc(int ch)
{
#ifdef CONSOLE_UART
  uint32_t int_status;

  esp_lowputc_disable_all_uart_int(CONSOLE_DEV.priv, &int_status);
#endif

  riscv_lowputc(ch);

#ifdef CONSOLE_UART
  esp_lowputc_restore_all_uart_int(CONSOLE_DEV.priv, &int_status);
#endif
}

#else /* HAVE_UART_DEVICE */

/****************************************************************************
 * Name: riscv_earlyserialinit, riscv_serialinit, and up_putc
 *
 * Description:
 *   Stubs that may be needed. These stubs will be used if all UARTs are
 *   disabled. In that case, the logic in common/xtensa_initialize.c is not
 *   smart enough to know that there are not UARTs and will still expect
 *   these interfaces to be provided.
 *   This may be a special case where the upper and lower half serial layers
 *   are added but other device is used as console.
 *   For more details, take a look at: nuttx/arch/xtensa/src/common/xtensa.h
 *

void esp_lowputc_restore_pins(const struct esp_uart_s *priv)
{
  /* Configure the pins */

  esp_configgpio(priv->txpin, INPUT);
  esp_gpio_matrix_out(priv->txpin, 0x100, false, false);

  esp_configgpio(priv->rxpin, INPUT);
  esp_gpio_matrix_in(priv->rxpin, 0x3c, false);
}

/****************************************************************************
 * Name: riscv_lowputc
 *
 * Description:
 *   Output one byte on the serial console.
 *
 * Parameters:
 *   ch        - Byte to be sent.
 *
 ****************************************************************************/

void riscv_lowputc(char ch)
{
#ifdef CONSOLE_UART
#  if defined(CONFIG_UART0_SERIAL_CONSOLE)
  struct esp_uart_s *priv = &g_uart0_config;
#  elif defined (CONFIG_UART1_SERIAL_CONSOLE)
  struct esp_uart_s *priv = &g_uart1_config;
#  endif

  /* Wait until the TX FIFO has space to insert new char */

  while (uart_hal_get_txfifo_len(priv->hal) == 0);

  /* Then send the character */

  esp_lowputc_send_byte(priv, ch);
#elif defined(CONFIG_ESPRESSIF_USBSERIAL)
  esp_usbserial_write(ch);
#endif /* CONSOLE_UART */
}

