#define NO_CPUINT                     ETS_INVALID_INUM

/* Masks for interrupt type used on esp_setup_irq */

#define ESP_CPUINT_IRAM_MASK       (1 << 1)
#define ESP_CPUINT_TRIGGER_MASK    (1 << 0)

/****************************************************************************
